INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/bete-de-lombre', 'Bête de l''Ombre', 'bete-de-lombre', 'bestiaire/marionette-de-lombre', 'bestiaire/marionette-de-lombre#bloc:ep5', 1, 'La Bête de l’Ombre est l’ultime métamorphose de l’invocation, une forme qui renonce définitivement à toute imitation humaine. Son corps est celui d’un humanoïde brisé et reconstruit dans une posture animale : la colonne vertébrale s’allonge de manière contre-nature, les épaules se disloquent, et les bras se transforment en puissantes pattes antérieures, terminées par des griffes démesurées capables de lacérer la pierre comme la chair. Son mouvement évoque moins une créature vivante qu’un cauchemar éveillé.', '65', 'fixe', 65, NULL, NULL, NULL, '50% de la barrière courante du lanceur', 'pct_barriere_lanceur', 50, '10 Armure Physique | 10 Armure Magique', 'separee', 10, 0, 10, 0, '5 cases sol / 5 cases nage', 5, 5, '8/8/8/0/0/8', 'bestiaire', 'Invocation › Marionette de lombre › D117:R144', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/carcalanche', 'Carcalanche', 'carcalanche', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-glace', 1, 'Le Carcalanche est un zombi figé par un froid si intense qu’il a momifié sa chair en la cristallisant. Son corps desséché, recouvert d''une peau grise et craquelée, ressemble à du cuir ancien tendu sur des os gelés. Ses yeux ont disparu depuis longtemps, remplacés par deux cavités où persiste une brume blanche et froide. Il crisse à chaque mouvement, comme si ses os râpaient sur de la glace vive.', '15/NPM', 'par_npm', 15, '5/NPM', 'par_npm', 5, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 5/NPM Armure Magique', 'separee', 0, 0, 5, 1, '4 cases sol / 0 case nage', 4, 0, '5/3/5/0/2/4 (+1 Force au niveau 2 magique, +1 Force au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › D233:R260', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/charcabe', 'Charcabé', 'charcabe', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-feu', 1, 'Le Charcabé est un non-mort incandescent, né de la fusion impie entre la nécromancie et la magie du feu. Contrairement aux zombis classiques rongés par la putréfaction, sa chair est calcinée jusqu''à ne plus être que du charbon craquelé, noir et rougeoyant. Des veines incandescentes parcourent son corps, comme des coulées de lave sous une croûte volcanique. Ses yeux, d’un rouge vif, brillent d’une lueur malsaine, témoins de la haine ardente qui voue à la vie sous toutes ses formes.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '1 Armure Physique et Magique/NPM', 'commune', 1, 1, 1, 1, '3 cases sol / 0 case nage', 3, 0, '5/3/5/0/5/4 (+1 Volonté au niveau 2 magique, +1 Volonté au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › D175:R202', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/crieur-osseux', 'Crieur osseux', 'crieur-osseux', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-vent', 2, 'Il s''agit d''un squelette à la mâchoire inférieure manquante mais qui semble être capable de pousser de formidables cris. D''après des légendes, ce sont des serviteurs de la Déesse du Vent mais dont la mission est obscure. Ces ossements très élancés dont les membres semblent tenir à la force du vent sont capables d''utiliser la magie du vent à leur avantage pour augmenter leur vitesse ou pousser des cris encore plus fort.', '5/NPM', 'par_npm', 5, '15/NPM', 'par_npm', 15, 'Selon le chakra', 'selon_chakra', NULL, '1 Armure Physique et Magique/NPM', 'commune', 1, 1, 1, 1, '5 cases sol / 0 case nage', 5, 0, '2/1/5/0/5/4 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › T291:AH318', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/double-sombre', 'Double sombre', 'double-sombre', 'bestiaire/marionette-de-lombre', 'bestiaire/marionette-de-lombre#bloc:ep3', 1, 'Le Double sombre atteint un degré de mimétisme presque parfait. Il adopte exactement les proportions du lanceur, reproduisant sa stature, sa démarche et jusqu’à ses postures de combat. Pourtant, malgré cette ressemblance saisissante, son visage demeure lisse et dépourvu de traits, uniquement percé de deux lueurs incandescentes là où devraient se trouver les yeux, brillant de la même couleur que ceux de son invocateur.', '40', 'fixe', 40, NULL, NULL, NULL, '30% de la barrière courante du lanceur', 'pct_barriere_lanceur', 30, '6 Armure Physique | 4 Armure Magique', 'separee', 6, 0, 4, 0, '4 cases sol / 4 cases nage', 4, 4, '6/6/6/0/0/6', 'bestiaire', 'Invocation › Marionette de lombre › D59:R86', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/embrase', 'Embrasé', 'embrase', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-feu', 2, 'Ce sont des condamnés à mort par le Temple du Feu pour des fautes graves envers le Temple, Séraphin ou même en dehors, ils sont purifiés dans la chambre des cendres par un feu particulier dont seul le Haut Prêtre du Feu a le secret. Toute la chair est brûlée, ne reste qu''une partie du squelette et les cendres, par une formule étrange, le squelette se relève, les parties manquantes sont cachées par les cendres et ils sont jetés dans le désert Doré près du Volcan, condamnés à errer le temps qu''ils doivent purger. Armé de son espadon arqué, il est prêt à traquer les intrus à son environnement.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '1 Armure Physique et Magique/NPM', 'commune', 1, 1, 1, 1, '4 cases sol / 0 case nage', 4, 0, '5/3/5/0/1/5 (+1 Force/Agilité au niveau 3 magique, +1 Force/Agilité au niveau 5 magique)', 'bestiaire', 'Invocation › Animation des morts › T175:AH202', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/executeur-lunaire', 'Exécuteur lunaire', 'executeur-lunaire', 'bestiaire/marionette-de-lombre', 'bestiaire/marionette-de-lombre#bloc:ep4', 1, 'L’Exécuteur lunaire est l’évolution monstrueuse de l''ombre du lanceur À l’instant de son invocation, ses proportions semblent croître sous les yeux des témoins, comme si l’ombre refusait toute limite imposée par la forme mortelle. Il conserve la silhouette du lanceur, mais celle-ci est exagérée jusqu’à l’effroi. Son visage reste lisse et dépourvu de traits, seulement animé par deux lueurs spectrales, identiques à celles du porteur. L’un de ses bras, gauche ou droit selon le bras fort du lanceur, se déploie démesurément pour former une griffe allongée.', '55', 'fixe', 55, NULL, NULL, NULL, '40% de la barrière courante du lanceur', 'pct_barriere_lanceur', 40, '6 Armure Physique | 8 Armure Magique', 'separee', 6, 0, 8, 0, '4 cases sol / 4 cases nage', 4, 4, '7/7/7/0/0/7', 'bestiaire', 'Invocation › Marionette de lombre › D88:R115', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/fantome', 'Fantôme', 'fantome', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-vide', 1, 'Des âmes errantes emplies de rancoeur et de rancune hantent les lieux qui furent autrefois leur foyer, leur champ de bataille ou bien errent sans but là où ils gisent. Bien que beaucoup de ces fantômes ne fassent que produire d''insupportables sanglots, ceux qui sont incapables d''accepter leur trépas peuvent se révéler être agressifs et puissants.', '7/NPM', 'par_npm', 7, '0', 'fixe', 0, '0', 'fixe', 0, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '5 cases sol / 0 case nage', 5, 0, '1/3/5/0/1/5 (+1 Agilité au niveau 2 magique, +1 Agilité au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › D117:R144', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/fulgurame', 'Fulgurâme', 'fulgurame', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-foudre', 2, 'Amalgâme entre os et métal, le Fulgurâme est un ancien soldat foudroyé par une magie trop puissante. Son âme, refusant la dissipation, s’est liée à l’orage qui l’a détruit. Son squelette est aujourd’hui parcouru par une énergie électrique résiduelle, ce qui lui permet avec sa lance en métal de foudroyer ses ennemis avec la même colère.
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-darcane', 'Golem d''arcane', 'golem-darcane', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-arcane', 1, 'Le Golem d''Arcane est un être que l''on peut considérer comme fantomatique. Son corps éthéré d''une blancheur écarlate flotte au-dessus des lieux chargés d''histoires où les combats entre mages ont été les plus féroces. Ce qui en fait un golem aux origines lacunaires et très rare dans la nature, à l''instar des golems issus des magies primordiales.', '5/NPM', 'par_npm', 5, '0', 'fixe', 0, '0', 'fixe', 0, '0 Armure Physique | 3/NPM Armure Magique', 'separee', 0, 0, 3, 1, '4 cases sol / 0 case nage', 4, 0, '5/5/10/1/1/1 (+1 Force au niveau 2 magique, +1 Force au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › D59:R86', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-de-boue', 'Golem de boue', 'golem-de-boue', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-eau', 1, 'Le golem de boue est une créature imposante, formée d’un mélange mouvant de terre détrempée et d’argile sombre. Son corps large et bosselé paraît sculpté dans un marais vivant, parcouru de fissures d’où s’échappe un limon gluant. Sa tête informe n’a souvent qu’une simple fente luisante en guise de regard, comme un œil unique suintant de vase. De ses bras massifs émergent de longues griffes tranchantes. Le golem de boue est le gardien silencieux des marécages et des rivières polluées, surgissant des eaux troubles pour défendre son territoire.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '4 cases sol / 8 cases nage', 4, 8, '1/5/10/1/1/5 (+1 Agilité au niveau 2 magique, +1 Agilité au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › D233:R260', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-de-chair', 'Golem de chair', 'golem-de-chair', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-sang', 1, 'Ce golem ne paie pas de mine par son apparence distordue mais la comble par sa potentielle force physique. Qui dit muscle dit forcément puissance à ne pas sous-estimer. Il possède aussi la capacité de modifier complètement son corps pour s''adapter à son environnement ou bien simplement de manière purement aléatoire, ce qui rappelle fortement les sorts de "Sang" et le sort "Taille disproportionné" de la magie du Sang.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '2 Armure Physique et Magique/NPM', 'commune', 2, 1, 2, 1, '4 cases sol / 0 case nage', 4, 0, '5/5/10/5/5/5', 'bestiaire', 'Invocation › Appel aux golems › D30:R57', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-de-cristal', 'Golem de cristal', 'golem-de-cristal', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-vide', 1, 'Surnommé aussi le “Chasseur invisible”, il s''agit d''un golem particulièrement dangereux. En effet, il possède la capacité unique de se rendre invisible à l''œil nu mais aussi capable d’ignorer toutes défenses. Ce chasseur défiant par sa présence les lois de l''univers, n''existe que pour traquer les êtres qui détiennent un savoir interdit.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '0 Armure Physique | 0 Armure Magique', 'separee', 0, 0, 0, 0, '4 cases sol / 4 cases nage', 4, 4, '1/5/10/1/1/5 (+1 Agilité au niveau 2 magique, +1 Agilité au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › D146:R173', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-de-foudre', 'Golem de foudre', 'golem-de-foudre', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-foudre', 1, 'Version évoluée des golems de mine, les golems de foudre sont des créatures très sophistiquées qui sont en grosse majorité d’origine artificielle. On peut en retrouver à l’état naturel mais ils sont assez facilement identifiables par leur apparence comme beaucoup plus bruts et moins sophistiqués que les artificiels. Ils sont parfaitement adaptés au travail dans les mines et sont même idéaux pour trouver des filons de métaux. Leur corps complètement fait de métal de différent type rendent son corps dur et capable d’attirer la foudre pour la redistribuer dans une autre direction.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '2/NPM Armure Physique | 2/NPM Armure Magique', 'separee', 2, 1, 2, 1, '5 cases sol / 0 case nage', 5, 0, '5/5/10/1/1/1 (+1 Force au niveau 2 magique, +1 Force au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › D349:R376', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-de-glace', 'Golem de glace', 'golem-de-glace', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-glace', 1, 'Le golem de glace est une imposante statue vivante, façonnée dans la plus pure des glaces, aux formes humaines parfaitement sculptées. Dépourvu de visage, il incarne l’absence d’âme et de compassion, avançant implacablement dans le blizzard éternel d’Enhor, son unique domaine. On ne le trouve que dans ces terres glacées, là où tempêtes et sommets enneigés forgent son essence. Contrairement à d’autres golems, il ne dispose d’aucune défense physique : ses membres de glace se brisent facilement.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '0 Armure Physique | 3/NPM Armure Magique', 'separee', 0, 0, 3, 1, '4 cases sol / 0 case nage', 4, 0, '5/5/10/1/1/1 (+1 Force au niveau 2 magique, +1 Force au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › D262:R289', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-de-lumiere', 'Golem de lumière', 'golem-de-lumiere', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-lumiere', 1, 'Le golem de lumière est une sentinelle élancée, forgée dans un matériau qui semble rayonner de l’intérieur. Plus petit et plus agile que les autres golems, il adopte toujours une silhouette féminine, en hommage à la déesse de la lumière. Il manie un arc façonné dans une matière translucide, capable de créer des flèches de lumière pure. Ces projectiles percent ses adversaires et peuvent aveugler leurs cibles à l’impact. Souvent posté sur les hauteurs ou aux abords des sanctuaires, il veille et frappe avec précision toute menace approchant.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '1/NPM Armure Physique | 1/NPM Armure Magique', 'separee', 1, 1, 1, 1, '5 cases sol / 0 case nage', 5, 0, '5/5/10/1/1/1 (+1 Force au niveau 2 magique, +1 Force au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › D378:R405', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-de-magma', 'Golem de magma', 'golem-de-magma', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-feu', 1, 'Le golem de magma est une créature née du feu et de la roche. Son corps est formé d’obsidienne noire parcourue de veines incandescentes, laissant échapper en permanence de la lave en fusion. On le rencontre dans les volcans ou dans les terres embrasées, où il erre à la recherche de nouvelles pierres à fusionner à son corps. Leurs bras, façonnés comme d’énormes canons, peuvent projeter des blocs de magma explosif capables de réduire en cendres murs, fortifications et champs entiers. C’est cette capacité qui a fait d’eux des armes vivantes redoutées, souvent exploitées comme machines de guerre par ceux qui parviennent à les contrôler.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '2 Armure Physique et Magique/NPM', 'commune', 2, 1, 2, 1, '3 cases sol / 0 case nage', 3, 0, '5/5/10/1/1/1 (+1 Perception au niveau 2 magique, +1 Perception au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › D204:R231', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-de-pain', 'Golem de pain', 'golem-de-pain', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-mono', 1, 'Ces Golems assez rares se retrouvent en majorité dans les cuisines, créés artificiellement pour protéger les précieuses provisions ou bien les champs de blé. Dans de plus rares cas, ils se retrouvent dans les champs de blé à entretenir le blé de manière naturelle pour des raisons encore inconnues. La différence entre les artificiels et les naturels est que les artificiels sont bien mieux travaillés et construits que les naturels.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '3/NPM Armure Physique | 3 Armure Magique', 'separee', 3, 1, 3, 0, '4 cases sol / 0 case nage', 4, 0, '5/1/10/1/1/1 (+1 Force au niveau 2 magique, +1 Force au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › D1:R28', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-de-petrole', 'Golem de pétrole', 'golem-de-petrole', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-corruption', 1, 'Le golem de pétrole est une créature aux origines mystérieuses. Selon des rumeurs, leur création proviendrait d''un mélange entre du brai et de la corruption. Mais certains affirment que le brai utilisé pour créer ces abominables golems n''est pas de la colle traditionnelle... Un des effets pervers de ces golems, c''est leur extrême inflammabilité. En effet, la moindre braise ou étincelle enflamme leur corps tout entier et les rend encore plus dangereux mais très faibles à l’eau.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '4 cases sol / 4 cases nage', 4, 4, '5/5/10/1/1/1 (+1 Perception au niveau 2 magique, +1 Perception au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › D88:R115', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-de-rouage', 'Golem de rouage', 'golem-de-rouage', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-espace-temps', 1, 'Le golem de Rouage est un gardien mécanique énigmatique, dont le corps est constitué d’innombrables engrenages de cuivre qui tournent sans jamais s’arrêter. Des lueurs rosées brillent dans ses zones sensibles, comme son cœur et sa tête, rappelant une énergie d’origine divine. Selon les légendes, ces colosses auraient été bénis par les dieux du Temps et de l’Espace afin de protéger les mystères les plus dangereux de ces magies.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '2/NPM Armure Physique | 2 Armure Magique', 'separee', 2, 1, 2, 0, '4 cases sol / 4 cases nage', 4, 4, '5/5/10/1/1/1 (+1 Perception au niveau 2 magique, +1 Perception au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › D117:R144', 'L''arbalécho est une arme étrange dont les bonus de dégâts ne rentrent pas dans la multiplication et la posture offensive met au max seulement le deuxième dé.');
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-de-sable', 'Golem de sable', 'golem-de-sable', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-vent', 1, 'On retrouve principalement cette créature dans les confins du désert doré. Là où les dunes se concentrent en petit comité et où les tempêtes font rage. Ce golem particulier est comme une sorte de squelette fait en sable durci dans lequel toutes les zones de vide sont comblées par du sable qui bouge en permanence, comme des sables mouvants. 
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-de-verre', 'Golem de verre', 'golem-de-verre', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-terre', 1, 'Les Golems de Verre sont des créatures que l''on retrouve principalement dans les déserts et verreries. Les rares spécimens trouvés à l''état naturel sont d''anciens golems de sable ayant subi une forte pression suite à une explosion de grande ampleur. Ce qui rend leur origine souvent difficile à expliquer, même si certains ont été créés accidentellement suite à des combats impliquant un puissant utilisateur du Feu. Pour ce qui est des spécimens artificiels, ils sont tout simplement créés par des maîtres-verriers, avec autant de raffinement et de précision que les sculpteurs de golems de marbre.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '2/NPM Armure Physique | 0 Armure Magique', 'separee', 2, 1, 0, 0, '4 cases sol / 0 case nage', 4, 0, '5/5/10/1/1/1 (+1 Force au niveau 2 magique, +1 Force au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › D291:R318', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-dombre', 'Golem d''ombre', 'golem-dombre', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-ombre', 1, 'Le golem de l’ombre est une silhouette élancée et élégante, sculptée dans une matière sombre qui absorbe la lumière autour de lui. Toujours raffiné, il porte l’apparence d’un noble ou d’un assassin masqué, rappelant le style sophistiqué du dieu de l’ombre. Ses mouvements sont silencieux, presque irréels, et ses contours semblent se fondre dans les ténèbres à chaque pas. Il manie deux lames formées d’ombre pure, qui se reforment instantanément lorsqu’elles sont brisées ou dissipées.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '1/NPM Armure Physique | 1/NPM Armure Magique', 'separee', 1, 1, 1, 1, '5 cases sol / 0 case nage', 5, 0, '1/5/10/1/1/5 (+1 Agilité au niveau 2 magique, +1 Agilité au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › D407:R434', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/golem-dos', 'Golem d''os', 'golem-dos', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-necromancie', 1, 'Le golem osseux est un amalgame de squelettes, portant avec eux toute la noirceur de leurs âmes dérangées de leur repos éternel. Les corps sont broyés pour constituer le corps de ce géant poussiéreux et sinistre, imitant l''anatomie d''un ogre ainsi que leur cruauté envers leurs collègues qu''ils fustigent de leur fouet squelettique.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '2/NPM Armure Physique | 0 Armure Magique', 'separee', 2, 1, 0, 0, '4 cases sol / 0 case nage', 4, 0, '5/5/10/1/1/1 (+1 Force au niveau 2 magique, +1 Force au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › D175:R202', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/goule', 'Goule', 'goule', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-corruption', 1, 'La Goule est un humanoïde corrompu, soit pré ou post-mortem. Les Humanoïdes Dégradés incapables de se nourrir suffisamment se transforment en goule dans une ultime tentative de dévorer un être encore sain. On raconte aussi que des Mort-Vivant ayant succombé à la corruption deviennent directement des goules. Leur chair s''est asséchée et leur sang est absent, sauf pour les cadavres bien frais, à peine transformés.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '2 Armure Physique et Magique/NPM', 'commune', 2, 1, 2, 1, '4 cases sol / 2 cases nage', 4, 2, '5/3/5/0/0/5 (+1 Force au niveau 3 magique, +1 Agilité au niveau 5 magique)', 'bestiaire', 'Invocation › Animation des morts › D59:R86', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/lumiphage', 'Lumiphage', 'lumiphage', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-lumiere', 2, 'Un squelette émanant d''une lumière aveuglante que l''on retrouve dans les anciens sites de culte de la Lumière. Selon les rumeurs, ce seraient d''anciens défenseurs de la Lumière parjures, suite à un dévouement trop prononcé pour Aurora. Ils auraient conclu un pacte mystérieux qui leur permet d''honorer malgré la mort et le manquement aux lois, de pourfendre le mal et de convertir les infidèles à la bonté de la Vierge Solaire.
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/momie', 'Momie', 'momie', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-espace-temps', 1, 'Ces humanoïdes entourés de bandelettes de lin ont été créés pour garder les tombes des défunts importants. Elles restent toujours à l’affût d’intrus qui pourraient venir profaner les lieux sacrés qu’elles protègent. Contrairement aux autres non-morts, les momies possèdent un sens de l’honneur et n’attaquent pas les vivants par haine.', '5/NPM', 'par_npm', 5, '15/NPM', 'par_npm', 15, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '4 cases sol / 0 case nage', 4, 0, '5/3/5/0/5/4 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › D88:R115', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/noctebre', 'Noctèbre', 'noctebre', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-ombre', 2, 'Le Noctèbre est le squelette d’un ancien assassin ou espion, relevé par la volonté d’Umbro pour servir à nouveau dans les ténèbres. Son corps est devenu presque intangible, liquide comme une ombre mouvante, et il n’apparaît jamais complètement à la lumière. Ce non-mort est un spécialiste des attaques dans les angles morts, il cherchera toujours à ne jamais attaquer un ennemi de face. Pas vu, pas pris, n''est-ce pas ?', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '0 Armure Physique | 0 Armure Magique', 'separee', 0, 0, 0, 0, '5 cases sol / 0 case nage', 5, 0, '1/5/5/0/1/5 (+1 Agilité au niveau 2 magique, +1 Agilité au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › T378:AH405', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/noye', 'Noyé', 'noye', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-eau', 1, 'Le Noyé est un cadavre rendu à la vie par les eaux stagnantes et putrides des marécages, des égouts ou des puits oubliés. Son corps a absorbé tant d’humidité qu’il en est devenu un réservoir vivant de liquides acides, vomissant sa haine pour la vie au travers d''un liquide corrosif. Là où il passe, la chair pourrit, et le métal rouille. En plus de ses dents acérées, son vomi est capable de pénétrer les armures et de tuer à petit feu ses adversaires.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '3 cases sol / 6 cases nage', 3, 6, '4/3/5/0/2/1 (+1 Force au niveau 2 magique, +1 Force au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › D204:R231', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/ombre-rampante', 'Ombre rampante', 'ombre-rampante', 'bestiaire/marionette-de-lombre', 'bestiaire/marionette-de-lombre#bloc:ep1', 1, 'L’Ombre rampante est une émanation imparfaite, arrachée de l’ombre du porteur avant même qu’elle n’ait une véritable forme. Elle se manifeste comme un voile sombre et mouvant, rampant au sol et le long des surfaces verticales, s’étirant et se contractant comme une nappe de ténèbres vivantes.', '15', 'fixe', 15, NULL, NULL, NULL, '10% de la barrière courante du lanceur', 'pct_barriere_lanceur', 10, '2 Armure Physique | 0 Armure Magique', 'separee', 2, 0, 0, 0, '4 cases sol / 4 cases nage', 4, 4, '5/5/5/0/0/5', 'bestiaire', 'Invocation › Marionette de lombre › D1:R28', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/os-degrades', 'Os dégradés', 'os-degrades', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-corruption', 2, 'Celui qui porte ce nom est un squelette boursouflé totalement infecté par la corruption, faisant partie de facto des solvités. Un liquide noir purulent dépasse de tous ses os et semble être prêt à exploser à n''importe quel moment. Ils sont capables de charger rapidement les adversaires et de se laisser exploser pour infliger de lourds dégâts contre les ennemis de son invocateur.', '1', 'fixe', 1, '0', 'fixe', 0, '10/NPM', 'par_npm', 10, '0 Armure Physique et Magique', 'commune', 0, 0, 0, 0, '4 cases sol / 4 cases nage', 4, 4, '1/3/5/0/0/5 (+1 Agilité au niveau 3 magique, +1 Agilité au niveau 5 magique)', 'bestiaire', 'Invocation › Animation des morts › T59:AH86', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/os-froid', 'Os froid', 'os-froid', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-glace', 2, 'Un squelette qu''on retrouve dans les zones froides de Maverick, si on en croit les légendes autour de ces morts, ce serait d''anciens fidèles de la Déesse de la Glace qui auraient prêté serment au-delà de la mort via un rituel encore méconnu. Une autre théorie parle d''ancien fidèle de la Déesse de la Glace qui aurait commis une faute très grave envers cette dernière et ont été condamné à répandre l''Hiver jusqu''à la destruction de leur carcasse.
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-aerienne', 'Poupée aérienne', 'poupee-aerienne', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-vent', 2, 'La poupée aérienne est faite de tissu léger, sans jambes, et lévite doucement au-dessus du sol, comme suspendue par un souffle invisible. Sa petite chevelure longue flotte derrière elle, rappelant celle de la déesse du Vent. Sa puissance réside dans la magie du vent et ses cris perçants, capables de désorienter quiconque s’approche trop près.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '4 cases sol / 0 case nage', 4, 0, '1/1/10/1/5/3 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › T320:AH347', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-arcanique', 'Poupée arcanique', 'poupee-arcanique', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-arcane', 2, 'La poupée de l’Arcane est une poupée assez étrange. Son corps est façonné dans un tissu gris uniforme, lisse et froid au toucher, sur lequel aucune couture n’est visible, comme s’il avait été créé d’un seul tenant. Sa forme est simple, presque banale, mais le chakra circule en elle, prêt à être exploité pour attaquer les ennemis', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '3 cases sol / 0 case nage', 3, 0, '1/1/10/1/5/3 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › T59:AH86', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-corrompu', 'Poupée corrompu', 'poupee-corrompu', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-corruption', 2, 'La poupée corrompue est une incarnation de la souillure. Son corps semble façonné dans une argile d’un noir absolu, si sombre qu’elle absorbe presque la lumière. Sa surface est constamment enduite de brai ou de pétrole, une matière visqueuse qui suinte lentement, comme si la poupée transpirait la corruption. Au toucher, elle est tiède et poisseuse, laissant une trace sombre derrière elle.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '3 cases sol / 0 case nage', 3, 0, '1/1/10/1/5/3 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › T88:AH115', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-de-glaise', 'Poupée de glaise', 'poupee-de-glaise', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-mono', 2, 'La Poupée de Glaise est une créature élémentaire rudimentaire, façonnée par magie à partir de terre humide ou d''argile. Elle ne paye pas de mine à première vue et pourtant, sous ses airs de petite figurine grossière, elle est dotée de la capacité de lancer des sorts basiques de la terre.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '3 cases sol / 0 case nage', 3, 0, '1/1/10/1/5/3 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › T1:AH28', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-flamboyante', 'Poupée flamboyante', 'poupee-flamboyante', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-feu', 2, 'La poupée flamboyante possède un corps sombre et craquelé, comme une céramique brûlée. À travers les fines fissures qui parcourent sa silhouette s’échappent des flammes vacillantes, illuminant son corps de lueurs orangées et rouges. Elle est chaude au toucher, parfois brûlante, et chaque mouvement provoque un léger crépitement.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '3 cases sol / 0 case nage', 3, 0, '1/1/10/1/5/3 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › T204:AH231', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-fulgurante', 'Poupée fulgurante', 'poupee-fulgurante', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-foudre', 2, 'La poupée fulgurante est entièrement métallique, avec des articulations visibles et des plaques finement ciselées. Des arcs de foudre courent constamment sur sa surface, crépitant et illuminant ses contours d’une lueur jaune. Sa nature est offensive : elle concentre la magie de la Foudre pour projeter des éclairs, électrocuter ses ennemis ou frapper rapidement avec des décharges précises.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '4 cases sol / 0 case nage', 4, 0, '1/1/10/1/5/3 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › T349:AH376', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-maudite', 'Poupée maudite', 'poupee-maudite', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-ombre', 2, 'La poupée maudite est faite de tissu sombre, mais son véritable danger vient de l’aura d’ombre qui l’entoure, rendant ses contours difficiles à distinguer. Elle se déplace silencieusement et attend le moment parfait pour frapper. Sa magie est subtile et insidieuse : elle entrave ses victimes, manipule les ombres autour d’elle, et attaque avec précision lorsqu’elles sont vulnérables.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '3 cases sol / 0 case nage', 3, 0, '1/1/10/1/5/3 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › T407:AH434', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-necrotique', 'Poupée nécrotique', 'poupee-necrotique', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-necromancie', 2, 'La poupée nécrotique est une petite sculpture articulée, entièrement façonnée dans des os finement taillés et polis. Chaque phalange, chaque côte miniature est assemblée avec une précision dérangeante, lui donnant une mobilité presque naturelle malgré sa rigidité apparente. Son corps est sec, pâle, et dégage une odeur de poussière et de mort ancienne. Lorsqu’elle bouge, ses os s’entrechoquent dans un cliquetis discret. La magie de la nécromancie circule entre ses jointures, lui permettant de capter les âmes et les exploiter pour ses sorts qui infligent le poison.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '3 cases sol / 0 case nage', 3, 0, '1/1/10/1/5/3 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › T175:AH202', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-oceanique', 'Poupée océanique', 'poupee-oceanique', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-eau', 2, 'La poupée océanique est façonnée de corail rugueux et d’algues humides, formant une silhouette inquiétante, hérissée de pointes et de filaments verdâtres. Des gouttes d’eau salée perlent en permanence sur son corps, et une odeur marine l’accompagne. Malgré son apparence effrayante, elle n’est pas agressive. Ses gestes sont lents et mesurés, et la magie de l’eau circule en elle pour apaiser, purifier et soigner.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '3 cases sol / 0 case nage', 3, 0, '1/1/10/1/5/3 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › T233:AH260', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-polaire', 'Poupée polaire', 'poupee-polaire', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-glace', 2, 'La poupée polaire prend la forme d’un petit humanoïde de neige, raffiné et presque sculptural, avec des contours nets et un visage expressif malgré sa matière glacée. Sa surface scintille légèrement. Elle utilise la magie de la glace pour créer des barrières protectrices et renforcer l''armure magique pour elle et ses alliés, agissant comme un petit gardien froid mais fiable.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '3 cases sol / 0 case nage', 3, 0, '1/1/10/1/5/3 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › T262:AH289', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-sacre', 'Poupée sacré', 'poupee-sacre', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-lumiere', 2, 'La poupée sacrée est façonnée en céramique lisse, prenant la forme d’une petite sentinelle élancée. Sa silhouette rappelle celle du golem de Lumière, avec des lignes nettes et harmonieuses qui inspirent calme et ordre. Là où le golem attaque, la poupée soigne les blessures.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '3 cases sol / 0 case nage', 3, 0, '1/1/10/1/5/3 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › T378:AH405', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-sanglante', 'Poupée sanglante', 'poupee-sanglante', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-sang', 2, 'La Poupée Sanglante est confectionnée à partir de chair tannée, de tissus humains et d’ossements délicats. Malgré sa taille enfantine, elle dégage une aura malsaine avec son sourire de l''ange.
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-temporelle', 'Poupée temporelle', 'poupee-temporelle', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-espace-temps', 2, 'La poupée temporelle est une créature étrange de l’espace-temps, faite à moitié de tissu usé, à moitié de rouages et d’engrenages miniatures, comme une petite poupée mécanique mal assemblée. Son corps émet parfois un léger cliquetis, même lorsqu’elle est immobile. Sa présence trouble la perception : son image semble légèrement en avance ou en retard sur ses mouvements. Quand elle lance des sorts elle se meut de manière très mécanique et bouge ses bras comme une horloge.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '3 cases sol / 0 case nage', 3, 0, '1/1/10/1/5/3 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › T117:AH144', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-terrestre', 'Poupée terrestre', 'poupee-terrestre', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-terre', 2, 'La poupée terrestre est un mini-hommage au dieu de la Terre. Son corps est façonné dans la pierre, les pièces reliées entre elles par des racines et des lianes, tandis que des plantes et herbes forment sa chevelure. Une grosse fleur émerge de son dos, et un bras est plus massif que l’autre, rappelant la force brute du dieu. Malgré son apparence imposante et robuste, elle reste une lanceuse de sort.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '3 cases sol / 0 case nage', 3, 0, '1/1/10/1/5/3 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › T291:AH318', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/poupee-vide', 'Poupée vide', 'poupee-vide', 'bestiaire/appel-aux-golems', 'bestiaire/appel-aux-golems#bloc:terre-vide', 2, 'L’étrange poupée du Vide ressemble à un petit fantôme silencieux. Son corps est dissimulé sous un tissu parfaitement blanc, immaculé, trop propre pour être naturel, percé de deux simples trous noirs laissant apparaître le vide là où devraient se trouver ses yeux. Il est difficile de décrire ce qu''il y a sous le tissu et peu importe...', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '3 cases sol / 0 case nage', 3, 0, '1/1/10/1/5/3 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Appel aux golems › T146:AH173', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/reanime', 'Réanimé', 'reanime', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-foudre', 1, 'Le Réanimé a la particularité d''avoir été ramené à la vie par des technomages nains. Les corps utilisés sont rarement de leur propre espèce, ils ont pour but d''extraire des ressources dans les mines les plus dangereuses. Leur utilisation dans les nations naines est règlementée mais certains nécromanciens et technomages passent entre les mailles du filet. En outre, ce sont des créatures sont équipées de prothèses magnétiques qui leur empêchent de perdre des membres bêtement, leur permettant de se reformer ou d''être réparés en cas d''éboulement.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '1 Armure Physique et Magique/NPM', 'commune', 1, 1, 1, 1, '5 cases sol / 0 case nage', 5, 0, '4/3/5/0/1/5 (+1 Agilité au niveau 2 magique, +1 Agilité au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › D320:R347', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/sihouetteur-obscur', 'Sihouetteur obscur', 'sihouetteur-obscur', 'bestiaire/marionette-de-lombre', 'bestiaire/marionette-de-lombre#bloc:ep2', 1, 'Le Silhouetteur obscur est une incarnation plus aboutie de l’ombre invoquée, déjà suffisamment stable pour adopter une posture humanoïde, bien que profondément imparfaite. Sa silhouette évoque vaguement celle d’un être vivant, mais son corps trahit sa nature artificielle : membres exagérément longs, articulations mal placées, et un visage totalement lisse, comme effacé avant d’avoir été achevé. Sa présence donne l’impression troublante d’un reflet qui aurait pris du retard sur la réalité.', '25', 'fixe', 25, NULL, NULL, NULL, '20% de la barrière courante du lanceur', 'pct_barriere_lanceur', 20, '2 Armure Physique | 4 Armure Magique', 'separee', 2, 0, 4, 0, '4 cases sol / 4 cases nage', 4, 4, '6/5/5/0/0/6', 'bestiaire', 'Invocation › Marionette de lombre › D30:R57', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/solecorche', 'Solécorché', 'solecorche', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-lumiere', 1, 'Le Solécorché est un cadavre réanimé non pas par de la magie noire, mais par une lumière sacrée corrompue. Autrefois purificatrice, cette lumière s’est infiltrée dans le corps en le maintenant en vie… mais en consumant peu à peu son enveloppe. Résultat : un non-mort brillant, mais en agonie permanente, brûlé de l’intérieur. Cette lumière qui le brûle lui donne beaucoup de puissance mais il reste que peu de temps sur le champ de bataille. Il se bat avec une lame qui semble être entièrement faite de lumière et qui semble le brûler lui-même.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '1 Armure Physique et Magique/NPM', 'commune', 1, 1, 1, 1, '4 cases sol / 0 case nage', 4, 0, '5/5/5/0/1/2 (+1 Force au niveau 2 magique, +1 Force au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › D349:R376', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/squamique', 'Squamique', 'squamique', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-arcane', 2, 'Le Squamique est un étrange squelette dont les os sont parfaitement blancs, rigides et fragiles, le tout avec des yeux parfaitement argentés et brillants. Ce non-mort est un lanceur de sort qui utilise tout l''aspect offensif et destructeur de la magie de l''arcane. Il est cependant vulnérable aux dégâts physiques et se fait rapidement réduire en morceaux.', '2/NPM', 'par_npm', 2, '12/NPM', 'par_npm', 12, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '4 cases sol / 4 cases nage', 4, 4, '2/3/5/0/5/1 (+1 Intelligence au niveau 2 magique, +1 Intelligence au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › T30:AH57', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/squelette-archer', 'Squelette archer', 'squelette-archer', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-mono', 2, 'Armés d''arcs rudimentaires, les Archers Squelettes s''attaquent inlassablement à tout ce qui vit. Leur totale absence de conscience leur permet de se lancer au combat sans réfléchir et de frapper en premier, mais leurs fragiles carcasses sont facilement réduites en pièces par l''ennemi.', '15/NPM', 'par_npm', 15, '0', 'fixe', 0, '0', 'fixe', 0, '1 Armure Physique et Magique/NPM', 'commune', 1, 1, 1, 1, '5 cases sol / 0 case nage', 5, 0, '3/3/5/0/0/4 (+1 Agilité au niveau 2 magique, +1 Agilité au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › T1:AH28', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/squelette-de-pierre', 'Squelette de pierre', 'squelette-de-pierre', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-terre', 2, 'Victime de la malédiction de la Pierre, une maladie d''origine d''une île éloignée. Ce pauvre être est arrivé au stade final où son corps entier s''est ossifié pour devenir un être totalement fait d''os, seuls persistent ses yeux ainsi que son cerveau (qui est touché lui aussi pour lui laisser le minimum).
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/squelette-venin', 'Squelette venin', 'squelette-venin', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-necromancie', 2, 'Le Squelette venin est un mort dont la moelle osseuse est totalement empoisonnée, mais malgré ça ce squelette exploite parfaitement bien ce poison qu''il insère dans ses victimes via ses griffes qu''il utilise avec beaucoup d''aisance. Il est aussi capable d''utiliser certains sorts de la nécromancie, ceux qui sont capables d''empoisonner.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '1 Armure Physique et Magique/NPM', 'commune', 1, 1, 1, 1, '5 cases sol / 0 case nage', 5, 0, '1/3/5/0/4/4 (+1 Agilité au niveau 2 magique, +1 Agilité au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › T146:AH173', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/squelrail', 'Squelrail', 'squelrail', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-eau', 2, 'Le Squelrail n’est pas qu’un squelette animé : c’est un corail ancien, vivant et conscient, qui a colonisé un cadavre immergé et s’en est servi comme armature pour croître. À la manière d’un parasite devenu hôte, le corail a remplacé chaque os par une excroissance minérale vivante. Le squelette ne pense pas… mais le corail, lui, pense lentement, ressent, et agit. Le résultat est une créature élégante, inquiétante et rigide, avançant sous l’eau avec majesté, et sur la terre comme une sculpture ambulante.', '7/NPM', 'par_npm', 7, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '1/NPM Armure Physique | 3/NPM Armure Magique', 'separee', 1, 1, 3, 1, '3 cases sol / 9 cases nage', 3, 9, '5/3/5/0/2/1 (+1 Force au niveau 2 magique, +1 Force au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › T204:AH231', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/temposs', 'Temposs', 'temposs', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-espace-temps', 2, 'Le Temposs est un mort ayant plus que la peau sur les os lui donnant une apparence assez effrayante, ces derniers brillent d''une couleur rose. C''est un lanceur hors pair capable d''utiliser les portails et téléportation pour lancer ses projectiles où il le souhaite.', '15/NPM', 'par_npm', 15, '0', 'fixe', 0, '0', 'fixe', 0, '0 Armure Physique | 2/NPM Armure Magique', 'separee', 0, 0, 2, 1, '4 cases sol / 0 case nage', 4, 0, '3/3/5/0/5/5 (+1 Agilité au niveau 3 magique)', 'bestiaire', 'Invocation › Animation des morts › T88:AH115', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/verros', 'Verros', 'verros', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-vide', 2, 'Le Verros est une étrange création revenue d’un plan où la matière elle-même se dissout dans l’absolu. Ses os ont été rongés par l’oubli de la dimension de Mora, puis reformés en une matière translucide, proche du verre ou du cristal. Il ne semble jamais totalement là, comme si son corps oscillait entre deux états d’existence. Il est un représentant de ce qu''est le vide sous sa forme la plus négative, rendant sa simple présence anxiogène.', '7/NPM', 'par_npm', 7, '0', 'fixe', 0, '0', 'fixe', 0, '0 Armure Physique | 0 Armure Magique', 'separee', 0, 0, 0, 0, '5 cases sol / 0 case nage', 5, 0, '1/3/5/0/1/5 (+1 Agilité au niveau 2 magique, +1 Agilité au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › T117:AH144', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/zombi', 'Zombi', 'zombi', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-mono', 1, 'Les zombis sont des cadavres en putréfaction ambulants qui chassent pour se nourrir de la vie qu’ils haïssent tant. Ce sont des créatures assez solides qui ne ressentent pas la douleur et qui mordent violemment leur victime avec leur morsure.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '2 Armure Physique et Magique/NPM', 'commune', 2, 1, 2, 1, '3 cases sol / 0 case nage', 3, 0, '3/3/5/0/0/3 (+1 Force au niveau 2 magique, +1 Force au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › D1:R28', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/zombi-ronce', 'Zombi ronce', 'zombi-ronce', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-terre', 1, 'Les zombi ronce portent ce nom car ils sont symbioses avec des végétaux assez étranges qui lui procurent une protection physique assez conséquente mais également des renforts pour ses poings et dents, ce qui lui permet de faire saigner ses proies. Malgré son manque d''intelligence, il est assez malin pour utiliser certains sorts de la terre ... notamment ceux qui renforcent la défense physique.', '15/NPM', 'par_npm', 15, '5/NPM', 'par_npm', 5, 'Selon le chakra', 'selon_chakra', NULL, '4/NPM Armure Physique | 4 Armure Magique', 'separee', 4, 1, 4, 0, '3 cases sol / 0 case nage', 3, 0, '5/3/5/0/5/1 (+1 Force au niveau 3 magique, +1 Force au niveau 5 magique)', 'bestiaire', 'Invocation › Animation des morts › D262:R289', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/zombi-soldat', 'Zombi soldat', 'zombi-soldat', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-necromancie', 1, 'Ces cadavres putréfiés sont réanimés par les Nécromanciens afin d''exterminer leurs ennemis et de propager des maladies. Bien que lents et maladroits, ils sont armés de grande hache de bataille, ce qui leur permet d''être plutôt efficaces sur le champ de bataille.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '2 Armure Physique et Magique/NPM', 'commune', 2, 1, 2, 1, '4 cases sol / 0 case nage', 4, 0, '4/4/5/0/0/1 (+1 Force au niveau 2 magique, +1 Force au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › D146:R173', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/zombinox', 'Zombinox', 'zombinox', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-arcane', 1, 'Le Zombinox est un zombie massif renforcé par des expériences arcanes/nécromancie. Sa peau saturée de magie le rend très endurant à tous les assauts qu''on pourrait lui faire. Les plus forts sont capables de surcharger leur corps pour libérer des boules de chakra qui vont pleuvoir sur les ennemis.', '15/NPM', 'par_npm', 15, '0', 'fixe', 0, '0', 'fixe', 0, '2 Armure Physique et Magique/NPM', 'commune', 2, 1, 2, 1, '3 cases sol / 0 case nage', 3, 0, '3/3/5/0/1/3 (+1 Force/Agilité au niveau 3 magique, +1 Force/Agilité au niveau 5 magique)', 'bestiaire', 'Invocation › Animation des morts › D30:R57', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/zombre', 'Zombre', 'zombre', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-ombre', 1, 'Les Zombres sont plus malins que la plupart de leurs congénères. Ils n''ont pas encore perdu leur cervelle et cela se voit très bien. Ils sont perfides, fourbes et sournois. Ils ne foncent pas tête baissée et préfèrent se focaliser sur leur proie, surtout les plus vulnérables. Ils peuvent manier plusieurs sorts de l''Ombre pour troubler l''esprit des faibles d''esprit. On retrouve évidemment ces monstres la nuit ou dans les lieux sombres et isolés où ils guettent en silence.', '10/NPM', 'par_npm', 10, '10/NPM', 'par_npm', 10, 'Selon le chakra', 'selon_chakra', NULL, '0 Armure Physique | 1/NPM Armure Magique', 'separee', 0, 0, 1, 1, '4 cases sol / 0 case nage', 4, 0, '4/4/5/0/5/1 (+1 Force au niveau 2 magique, +1 Force au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › D378:R405', NULL);
INSERT INTO creature (id, nom, nom_cle, invocation_id, bloc_id, rang, description, sante_brut, sante_forme, sante_valeur, chakra_brut, chakra_forme, chakra_valeur, barriere_brut, barriere_forme, barriere_valeur, defense_brut, defense_forme, armure_physique, armure_physique_par_npm, armure_magique, armure_magique_par_npm, vitesse_brut, vitesse_sol, vitesse_nage, fpvsia_brut, origine, source_ref, remarque) VALUES ('bestiaire/zompi', 'Zompi', 'zompi', 'bestiaire/animation-des-morts', 'bestiaire/animation-des-morts#bloc:necromancie-vent', 1, 'Le Zompi est un cadavre réanimé par un champignon parasite d’origine inconnue. Ce dernier s’empare du système nerveux et musculaire de son hôte mort, le faisant bouger avec des gestes saccadés, comme tiré par des fils invisibles. Le champignon prolifère à travers le corps en formant des excroissances mycosiques : des chapeaux difformes, des amas de spores sur le dos, et des filaments qui s’échappent des yeux, de la bouche ou des plaies ouvertes. Sa peau en décomposition est percée de racines fongiques qui le maintiennent debout bien après la mort.', '20/NPM', 'par_npm', 20, '0', 'fixe', 0, '0', 'fixe', 0, '1 Armure Physique et Magique/NPM', 'commune', 1, 1, 1, 1, '4 cases sol / 0 case nage', 4, 0, '2/1/5/0/1/5 (+1 Agilité au niveau 2 magique, +1 Agilité au niveau 4 magique)', 'bestiaire', 'Invocation › Animation des morts › D291:R318', NULL);
